#!/usr/bin/env python3
"""Small, pure-Python implementation of the documented GNU sed subset."""
import os
import re
import sys

CLASSES = {
    'alnum': 'A-Za-z0-9', 'alpha': 'A-Za-z', 'blank': ' \\t',
    'cntrl': '\\x00-\\x1f\\x7f', 'digit': '0-9', 'graph': '\\x21-\\x7e',
    'lower': 'a-z', 'print': '\\x20-\\x7e', 'punct': '!-/:-@[-`{-~',
    'space': ' \\t\\r\\n\\v\\f', 'upper': 'A-Z', 'xdigit': 'A-Fa-f0-9'
}


def expand_classes(s):
    for k, v in CLASSES.items():
        s = s.replace('[:' + k + ':]', v)
    return s


def regex_translate(src, extended=False):
    """Translate the requested GNU ASCII BRE/ERE subset to Python syntax."""
    out = []
    i = 0
    in_class = False
    while i < len(src):
        c = src[i]
        if c == '[' and not in_class:
            j = i + 1
            if j < len(src) and src[j] == '^': j += 1
            if j < len(src) and src[j] == ']': j += 1
            while j < len(src):
                if src[j] == ']' and not (j and src[j-1] == '\\'):
                    break
                j += 1
            if j < len(src):
                z = expand_classes(src[i:j+1])
                out.append(z); i = j + 1; continue
        if c == '\\' and i + 1 < len(src):
            d = src[i+1]; i += 2
            escapes = {'a':'\\a','f':'\\f','n':'\\n','r':'\\r','t':'\\t','v':'\\v',
                       'w':'[A-Za-z0-9_]','W':'[^A-Za-z0-9_]','s':'[ \\t\\r\\n\\v\\f]',
                       'S':'[^ \\t\\r\\n\\v\\f]','b':'(?:(?<=\\w)(?!\\w)|(?<!\\w)(?=\\w))',
                       'B':'(?:(?<=\\w)(?=\\w)|(?<!\\w)(?!\\w))',
                       '<':'(?<![A-Za-z0-9_])(?=[A-Za-z0-9_])',
                       '>':'(?<=[A-Za-z0-9_])(?![A-Za-z0-9_])'}
            if d in escapes: out.append(escapes[d])
            elif not extended and d in '()+?|': out.append(d)
            elif not extended and d == '{': out.append('{')
            elif not extended and d == '}': out.append('}')
            elif d.isdigit(): out.append('\\' + d)
            else: out.append(re.escape(d))
            continue
        if not extended and c in '()+?|{}': out.append('\\' + c)
        elif extended and c in '(){}+?|': out.append(c)
        elif c == '\x00': out.append('\\x00')
        else: out.append(c)
        i += 1
    return ''.join(out)


class RX:
    def __init__(self, source, extended):
        self.source = source
        try:
            self.r = re.compile(regex_translate(source, extended), re.ASCII)
        except re.error:
            self.r = re.compile(r'(?!x)x')

    def search(self, text, start=0):
        # Determine POSIX leftmost-longest by fixing each possible start and
        # trying all endpoints longest first. fullmatch(pos,endpos) keeps
        # anchors relative to the original string.
        for a in range(start, len(text) + 1):
            for b in range(len(text), a - 1, -1):
                m = self.r.fullmatch(text, a, b)
                if m is not None:
                    return m
        return None


class Addr:
    def __init__(self, kind, val=None): self.kind, self.val = kind, val

class Command:
    def __init__(self):
        self.a1 = self.a2 = None; self.neg = False; self.op = ''
        self.arg = None; self.range_on = False; self.zero_range = False


class Parser:
    def __init__(self, s, extended):
        self.s, self.i, self.extended = s, 0, extended
        self.commands = []; self.labels = {}; self.last_rx = None

    def ws(self):
        while self.i < len(self.s) and self.s[self.i] in ' \t\r': self.i += 1

    def delimited(self, delim):
        out = []; self.i += 1
        while self.i < len(self.s):
            c = self.s[self.i]; self.i += 1
            if c == delim: return ''.join(out)
            if c == '\\' and self.i < len(self.s):
                d = self.s[self.i]; self.i += 1
                if d == delim: out.append(delim)
                else: out.extend(('\\', d))
            else: out.append(c)
        return ''.join(out)

    def addr(self):
        self.ws()
        if self.i >= len(self.s): return None
        st = self.i; c = self.s[self.i]
        if c.isdigit():
            while self.i < len(self.s) and self.s[self.i].isdigit(): self.i += 1
            n = int(self.s[st:self.i])
            if self.i < len(self.s) and self.s[self.i] == '~':
                self.i += 1; q = self.i
                while self.i < len(self.s) and self.s[self.i].isdigit(): self.i += 1
                return Addr('step', (n, int(self.s[q:self.i])))
            return Addr('num', n)
        if c == '$': self.i += 1; return Addr('last')
        if c == '/':
            z = self.delimited('/'); return Addr('rx', z)
        if c == '\\' and self.i + 1 < len(self.s):
            d = self.s[self.i+1]
            if not d.isalnum() and d != '\\':
                self.i += 1; z = self.delimited(d); return Addr('rx', z)
        return None

    def linearg(self):
        st = self.i
        while self.i < len(self.s) and self.s[self.i] not in '\n;': self.i += 1
        return self.s[st:self.i].strip()

    def textarg(self):
        # one-line: command whitespace text.  Traditional: command \ newline,
        # with backslash-newline continuing embedded text lines.
        while self.i < len(self.s) and self.s[self.i] in ' \t': self.i += 1
        if self.i < len(self.s) and self.s[self.i] == '\\' and self.i+1 < len(self.s) and self.s[self.i+1] == '\n':
            self.i += 2; out = []
            while self.i < len(self.s):
                j = self.s.find('\n', self.i)
                if j < 0: out.append(self.s[self.i:]); self.i = len(self.s); break
                part = self.s[self.i:j]
                if part.endswith('\\'):
                    out.append(part[:-1]); out.append('\n'); self.i = j + 1
                else:
                    out.append(part); self.i = j; break
            return ''.join(out)
        st = self.i
        while self.i < len(self.s) and self.s[self.i] != '\n': self.i += 1
        return self.s[st:self.i]

    def subst(self):
        delim = self.s[self.i]; pat = self.delimited(delim)
        rep = self.delimited(delim)
        st = self.i
        while self.i < len(self.s) and self.s[self.i] not in ';\n}': self.i += 1
        flags = self.s[st:self.i].strip()
        return (pat, rep, flags)

    def parse(self):
        depth = []
        while self.i < len(self.s):
            self.ws()
            if self.i >= len(self.s): break
            if self.s[self.i] in '\n;': self.i += 1; continue
            if self.s[self.i] == '#':
                j = self.s.find('\n', self.i); self.i = len(self.s) if j < 0 else j; continue
            if self.s[self.i] == '}':
                self.i += 1
                if depth:
                    o = depth.pop(); self.commands[o].arg = len(self.commands)
                continue
            c = Command(); save = self.i; c.a1 = self.addr()
            if c.a1:
                self.ws()
                if self.i < len(self.s) and self.s[self.i] == ',':
                    self.i += 1; self.ws()
                    if self.i < len(self.s) and self.s[self.i] in '+~':
                        k = self.s[self.i]; self.i += 1; q = self.i
                        while self.i < len(self.s) and self.s[self.i].isdigit(): self.i += 1
                        c.a2 = Addr('plus' if k == '+' else 'tilde', int(self.s[q:self.i]))
                    else: c.a2 = self.addr()
            else: self.i = save
            self.ws()
            if self.i < len(self.s) and self.s[self.i] == '!': c.neg = True; self.i += 1; self.ws()
            if self.i >= len(self.s): break
            c.op = self.s[self.i]; self.i += 1
            idx = len(self.commands); self.commands.append(c)
            if c.op == '{': depth.append(idx)
            elif c.op == ':':
                c.arg = self.linearg(); self.labels[c.arg] = idx
            elif c.op in 'btT': c.arg = self.linearg()
            elif c.op in 'aic': c.arg = self.textarg()
            elif c.op == 's': c.arg = self.subst()
            elif c.op in 'qQ':
                self.ws(); q = self.i
                while self.i < len(self.s) and self.s[self.i].isdigit(): self.i += 1
                c.arg = int(self.s[q:self.i] or '0')
            elif c.op not in '=dDgGhHxnNpPz':
                self.linearg()
        for o in depth: self.commands[o].arg = len(self.commands)
        return self.commands, self.labels


class Engine:
    def __init__(self, cmds, labels, extended=False, quiet=False):
        self.cs, self.labels, self.extended, self.quiet = cmds, labels, extended, quiet
        self.hold = ''; self.last_regex = None; self.out = []; self.status = 0
        self.subbed = False; self.appendq = []

    def rx(self, source):
        if source == '':
            return self.last_regex
        self.last_regex = RX(source, self.extended); return self.last_regex

    def amatch(self, a, pat, num, last, start_num=None):
        if a.kind == 'num': return num == a.val
        if a.kind == 'last': return last
        if a.kind == 'step':
            first, step = a.val
            return num >= first and (num-first) % step == 0
        if a.kind == 'rx':
            r = self.rx(a.val); return r is not None and r.search(pat) is not None
        if a.kind == 'plus': return num >= start_num + a.val
        if a.kind == 'tilde': return num % a.val == 0
        return False

    def selected(self, c, pat, num, last):
        if c.a1 is None: v = True
        elif c.a2 is None: v = self.amatch(c.a1, pat, num, last)
        else:
            if not c.range_on:
                # GNU special 0,/re/ begins active before line 1.
                if c.a1.kind == 'num' and c.a1.val == 0:
                    c.range_on = True; c.range_start = 0
                elif self.amatch(c.a1, pat, num, last):
                    c.range_on = True; c.range_start = num
                    if c.a2.kind == 'num' and c.a2.val <= num: c.range_on = False
                    v = True
                    return not v if c.neg else v
            if c.range_on:
                v = True
                test = True
                if num == c.range_start and c.a2.kind == 'rx': test = False
                if test and self.amatch(c.a2, pat, num, last, c.range_start): c.range_on = False
            else: v = False
        return not v if c.neg else v

    def replacement(self, rep, m):
        out=[]; i=0
        while i < len(rep):
            if rep[i] == '&': out.append(m.group(0)); i += 1
            elif rep[i] == '\\' and i+1 < len(rep):
                d=rep[i+1]; i += 2
                if d.isdigit():
                    try: out.append(m.group(int(d)) or '')
                    except IndexError: pass
                elif d in 'afnrtv': out.append({'a':'\a','f':'\f','n':'\n','r':'\r','t':'\t','v':'\v'}[d])
                else: out.append(d)
            else: out.append(rep[i]); i += 1
        return ''.join(out)

    def substitute(self, pat, spec):
        source, rep, flags = spec; r = self.rx(source)
        if r is None: return pat, False
        g = 'g' in flags; pflag = 'p' in flags
