        nth = nums[-1] if nums else None
        out=[]; pos=0; count=0; changed=False; last_empty=-1
        while pos <= len(pat):
            m = r.search(pat, pos)
            if not m: break
            count += 1
            use = (nth is None or count >= nth) and (g or nth is None or count == nth)
            if use:
                out.append(pat[pos:m.start()]); out.append(self.replacement(rep,m)); changed=True
                pos=m.end()
                if not g: break
            else:
                out.append(pat[pos:m.end()]); pos=m.end()
            if m.end() == m.start():
                if pos >= len(pat): break
                out.append(pat[pos]); pos += 1
        out.append(pat[pos:]); new=''.join(out)
        if changed and pflag: self.out.append(new+'\n')
        return new, changed

    def flushq(self):
        for x in self.appendq: self.out.append(x + '\n')
        self.appendq=[]

    def run(self, records):
        # records is list of (text, number, is_last)
        k=0; pat=''
        while k < len(records):
            pat,num,last=records[k]; self.subbed=False; pc=0; deleted=False
            while pc < len(self.cs):
                c=self.cs[pc]
                if not self.selected(c,pat,num,last): pc += 1; continue
                o=c.op
                if o=='{': pc += 1
                elif o=='}' or o==':': pc += 1
                elif o=='a': self.appendq.append(c.arg); pc += 1
                elif o=='i': self.out.append(c.arg+'\n'); pc += 1
                elif o=='c':
                    # A range emits once, when it closes (or one-address line).
                    if c.a2 is None or not c.range_on: self.out.append(c.arg+'\n')
                    deleted=True; break
                elif o=='d': deleted=True; break
                elif o=='D':
                    q=pat.find('\n')
                    if q<0: deleted=True; break
                    pat=pat[q+1:]; pc=0
                elif o=='g': pat=self.hold; pc += 1
                elif o=='G': pat += '\n'+self.hold; pc += 1
                elif o=='h': self.hold=pat; pc += 1
                elif o=='H': self.hold += '\n'+pat; pc += 1
                elif o=='x': pat,self.hold=self.hold,pat; pc += 1
                elif o=='p': self.out.append(pat+'\n'); pc += 1
                elif o=='P': self.out.append(pat.split('\n',1)[0]+'\n'); pc += 1
                elif o=='=': self.out.append(str(num)+'\n'); pc += 1
                elif o=='z': pat=''; pc += 1
                elif o=='s':
                    pat,ch=self.substitute(pat,c.arg); self.subbed |= ch; pc += 1
                elif o in 'btT':
                    take = o=='b' or (o=='t' and self.subbed) or (o=='T' and not self.subbed)
                    if o in 'tT': self.subbed=False
                    if take:
                        pc = self.labels.get(c.arg, len(self.cs)) if c.arg else len(self.cs)
                    else: pc += 1
                elif o in 'qQ':
                    if o=='q' and not self.quiet: self.out.append(pat+'\n')
                    self.flushq(); self.status=c.arg; return
                elif o=='n':
                    if not self.quiet: self.out.append(pat+'\n')
                    self.flushq(); k += 1
                    if k>=len(records): return
                    pat,num,last=records[k]; self.subbed=False; pc += 1
                elif o=='N':
                    k += 1
                    if k>=len(records):
                        if not self.quiet: self.out.append(pat+'\n')
                        self.flushq(); return
                    p2,n2,last2=records[k]; pat += '\n'+p2; num,last=n2,last2; pc += 1
                else: pc += 1
            if not deleted and not self.quiet: self.out.append(pat+'\n')
            self.flushq(); k += 1


def main(argv):
    quiet=extended=separate=False; scripts=[]; i=0
    while i<len(argv) and argv[i] in ('-n','-E','-s','-e'):
        if argv[i]=='-n': quiet=True; i+=1
        elif argv[i]=='-E': extended=True; i+=1
        elif argv[i]=='-s': separate=True; i+=1
        else:
            if i+1>=len(argv): return 1
            scripts.append(argv[i+1]); i+=2
    if not scripts:
        if i>=len(argv): return 1
        scripts=[argv[i]]; i+=1
    script='\n'.join(scripts)
    if script.startswith('#n'): quiet=True
    try: cmds,labels=Parser(script,extended).parse()
    except Exception as e:
        sys.stderr.write('sed: '+str(e)+'\n'); return 1
    files=argv[i:]; chunks=[]; bad=False
    if not files:
        chunks=[sys.stdin.buffer.read().decode('latin1')]
    else:
        for f in files:
            if f=='-': chunks.append(sys.stdin.buffer.read().decode('latin1'))
            else:
                try:
                    with open(f,'rb') as h: chunks.append(h.read().decode('latin1'))
                except OSError as e:
                    sys.stderr.write('sed: cannot read '+f+': '+str(e)+'\n'); bad=True
    eng=Engine(cmds,labels,extended,quiet)
    if separate:
        for data in chunks:
            for c in cmds: c.range_on=False
            lines=data.splitlines()
            rec=[(x,j+1,j==len(lines)-1) for j,x in enumerate(lines)]
            eng.run(rec)
    else:
        lines=[]
        for data in chunks: lines.extend(data.splitlines())
        rec=[(x,j+1,j==len(lines)-1) for j,x in enumerate(lines)]
        eng.run(rec)
    sys.stdout.buffer.write(''.join(eng.out).encode('latin1'))
    return eng.status if eng.status else (2 if bad else 0)

if __name__=='__main__':
    sys.exit(main(sys.argv[1:]))
